package com.spms.entity;import jakarta.persistence.*;import lombok.*;import java.math.*;import java.time.*;import java.util.*;@Entity @Table(uniqueConstraints=@UniqueConstraint(columnNames={"employee_id","pay_period"})) @Getter @Setter @NoArgsConstructor public class PayrollRecord{public enum Status{DRAFT,PUBLISHED}@Id @GeneratedValue private UUID id;@ManyToOne(optional=false)private Employee employee;@Column(name="pay_period")private LocalDate payPeriod;private BigDecimal basicPay=BigDecimal.ZERO;private BigDecimal allowances=BigDecimal.ZERO;private BigDecimal deductions=BigDecimal.ZERO;private BigDecimal netPay=BigDecimal.ZERO;@Enumerated(EnumType.STRING)private Status status=Status.DRAFT;private LocalDateTime publishedAt;}